themes=[('blueprint','باراد / مهندسی','سرمه‌ای و آبی؛ پیشنهاد اصلی برای سبد وسیع','جست‌وجوی مدل در هدر، دو ورودی برند، فیلتر کناری و جدول مشخصات. مناسب انتخاب سریع کابل برق و کنترل.'),('studio','باراد / روشن','سفید و مسی؛ ساده و منظم','بنر با تصویر قوسی، فاصله‌های آرام، فیلتر افقی و کارت‌های مرتب. مناسب تأکید بر برند و خوانایی.'),('signal','باراد / ارتباط','سبز تیره و لیمویی؛ زیرساخت ارتباط','بنر دو بخش، کارت‌های برند تیره و نمایش برجسته خانواده‌های نوری و مخابراتی کنار محصولات برق.')]
pages=[('home','خانه'),('catalog','تمام کالاها'),('product','محصول'),('quote','پیش‌فاکتور'),('about','درباره باراد'),('contact','تماس')]
def gallery(t):
    tid,name,tag,desc=t
    tabs=''.join(f'<button id="tab-{tid}-{p}" role="tab" aria-controls="panel-{tid}-{p}" aria-selected="{str(i==0).lower()}" data-live="barad-template-preview.html?theme={tid}&amp;page={p}">{n}</button>' for i,(p,n) in enumerate(pages))
    panels=''
    for i,(p,n) in enumerate(pages):
        shots=''
        for view,label,w in [('desktop','دسکتاپ',1440),('mobile','گوشی',390)]:
            src=f'assets/templates/barad/{tid}-{p}-{view}.webp'
            h=Image.open(ROOT/src).height if (ROOT/src).exists() else 2000
            shots+=f'<figure class="br-shot {view}"><figcaption><span>{n} · {label}</span><a href="{src}" download>دریافت تصویر ↓</a></figcaption><div class="br-window" tabindex="0" aria-label="تصویر کامل {n} در {label}؛ داخل قاب به پایین اسکرول کنید"><img {"src" if i==0 else "data-src"}="{src}" alt="طرح {name}؛ صفحه {n} در {label}" width="{w}" height="{h}" loading="lazy" decoding="async"></div></figure>'
        panels+=f'<div class="br-pair" id="panel-{tid}-{p}" role="tabpanel" aria-labelledby="tab-{tid}-{p}" {"hidden" if i else ""}>{shots}</div>'
    return f'<section class="br-gallery" id="barad-{tid}"><div class="br-gallery-head"><div><h2>{name}</h2><p>{tag}</p></div><a class="br-live" href="barad-template-preview.html?theme={tid}&amp;page=home" target="_blank" rel="noopener">نسخه تعاملی همین صفحه ↗</a></div><div class="br-tabs" role="tablist" aria-label="صفحات طرح {name}">{tabs}</div>{panels}</section>'
cards=''.join(f'<article class="br-card"><small>{tag}</small><h3>{name}</h3><p>{desc}</p><a href="#barad-{tid}">مشاهده شش صفحه ←</a></article>' for tid,name,tag,desc in themes)
nav='<nav class="site-nav"><div class="wrap"><a class="site-brand" href="index.html">پرونده بازار کابل</a><div class="nav-links"><a href="index.html">نقشه راه</a><a href="competitors.html">رقبا</a><a href="design.html">طراحی</a><a href="woodmart-templates.html">وودمارت</a><a href="barad-templates.html" aria-current="page">طرح‌های باراد</a><a href="security.html">امنیت</a><a href="seo-roadmap.html">سئو</a><a href="client-brief.html">اطلاعات کارفرما</a></div><div class="nav-actions"><button class="icon-btn" id="theme-toggle" aria-label="تغییر تم">☀</button></div></div></nav>'
sources=[('https://www.khorasanelectric.com/index.php/fa/about-us/resellers.html','فهرست رسمی نمایندگان افشارنژاد','نام باراد، دامنه، نشانی و تلفن ۰۲۱۲۱۰۰۰۰۰۱ درج شده است.'),('https://www.khorasanelectric.com/index.php/fa/','خانواده‌های محصولات افشارنژاد','مرجع درخت اولیه دسته‌بندی؛ نه اعلام موجودی باراد.'),('https://www.khorasanelectric.com/index.php/fa/products/fixed-installation-cables/pvc-insulated-cables/power-cables.html','مدل‌های NYY و NYM','مشخصات پایه نمونه‌ها از صفحه سازنده.'),('https://www.khorasanelectric.com/index.php/fa/products/multicore-cables/digital-control-cables.html','مدل‌های NYSLY و NYSLYCY','نام مدل و ولتاژ پایه؛ تنوع‌ها به دیتاشیت نیاز دارند.'),('https://sgccir.com/','سایت رسمی شهید قندی','تأیید خانواده‌های نوری و مخابراتی مسی؛ کاتالوگ مدل‌ها در این بررسی قابل استخراج نبود.'),('https://t.me/s/Barad_Innovators_co','کانال معرفی باراد','منبع تکمیلی حوزه فعالیت؛ تلفن قدیمی با فهرست کارخانه متفاوت است.'),('https://woodmarttheme.com/docs/layouts-builder/','WoodMart Layouts Builder','چیدمان صفحه محصول و آرشیو با المنتور؛ کارت کاملاً اختصاصی با Gutenberg.'),('https://woodmarttheme.com/docs/create-a-slider/','اسلایدر وودمارت','بنرهای قابل ویرایش با متن واقعی خارج از تصویر.'),('https://woocommerce.com/document/product-csv-importer-exporter/','ورود و به‌روزرسانی کالا با CSV','اطلاعات محصول در ووکامرس، جدا از طراحی المنتور.')]
