s=wm.read_text(encoding='utf-8')
banner='<section class="barad-banner" id="barad-current"><div class="kicker">طرح‌های فعلی پروژه · ایده‌آفرینان باراد</div><h2>سه هویت جدید با برند و محصولات واقعی</h2><p>افشارنژاد خراسان و شهید قندی؛ خانه، تمام کالاها، محصول، پیش‌فاکتور مهمان، درباره ما و تماس. ۳۶ تصویر گوشی و دسکتاپ همراه با راهنمای اجرای المنتور. مجموعه‌های پایین، آرشیو کانسپت‌های عمومی‌اند؛ حساب و ورود موجود در آن‌ها جزو دامنه فعلی باراد نیست.</p><a href="barad-templates.html">ورود به استودیو اختصاصی باراد ←</a></section>'
if '<!-- barad-current-start -->' in s:
    s=re.sub(r'<!-- barad-current-start -->.*?<!-- barad-current-end -->','<!-- barad-current-start -->'+banner+'<!-- barad-current-end -->',s,flags=re.S)
else:s=s.replace('<main class="wrap page-main">','<main class="wrap page-main"><!-- barad-current-start -->'+banner+'<!-- barad-current-end -->',1)
if 'href="barad-templates.css"' not in s:s=s.replace('</head>','<link rel="stylesheet" href="barad-templates.css"></head>',1)
